from pathlib import Path
try:
 from lupa.lua51 import LuaRuntime
except ImportError as exc:
 raise SystemExit('Install the test dependency first: python -m pip install lupa==2.8') from exc
ROOT=Path(__file__).resolve().parents[1]
ADDON=ROOT/'addon/BuffTap'
tests=[]
def test(name,code):
 lua=LuaRuntime(unpack_returned_tuples=True)
 lua.execute((ROOT/'tests/mock.lua').read_text())
 ns=lua.table()
 for f in ['Catalog.lua','Engine.lua','ConsumableData.lua','Consumables.lua','WeaponCoatings.lua','BuffTap.lua','Options.lua']:
  lua.execute((ADDON/f).read_text(encoding='utf-8-sig'),'BuffTap',ns)
 lua.execute('BuffTap:InitDB(); BuffTap:Refresh()')
 lua.execute(code)
 tests.append(name); print('PASS',name)

test('Highest known rank, exact secure spell and binding', "assert(BuffTap.action.id==5232); assert(BuffTap.button.attrs.spell==5232); assert(bindings.MOUSEWHEELDOWN)")
test('Applied buffs advance and release overrides', "aura('player',5232,'Mark of the Wild'); refresh(); assert(BuffTap.action.id==467); aura('player',467,'Thorns'); refresh(); assert(not BuffTap.action and not BuffTap.button.attrs.type1 and not next(bindings))")
test('Aura failures and secret records fail closed', "C_UnitAuras.GetAuraDataByIndex=function() error('blocked') end; refresh(); assert(not BuffTap.action); C_UnitAuras.GetAuraDataByIndex=function() return {secret=true} end; refresh(); assert(not BuffTap.action)")
test('Global secrecy cannot reuse cached auras', "C_Secrets={ShouldAurasBeSecret=function() return true end}; BuffTap.events.scripts.OnEvent(nil,'ADDON_RESTRICTION_STATE_CHANGED'); advance(.1); assert(not BuffTap.action)")
test('Mouse click refuses changed target identity', "BuffTap.db.group=true; BuffTap.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild'); refresh(); assert(BuffTap.action.target=='party1'); local old=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Other' or old(u) end; BuffTap.button.scripts.PreClick(nil,'LeftButton',false); assert(not BuffTap.action)")
test('Combat clears payload, bindings and timers without insecure writes', "combat=true; safety('blocked'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_DISABLED'); BuffTap:Refresh(); BuffTap.button.scripts.PreClick(nil,'LeftButton',false); assert(not BuffTap.action and not next(bindings)); assert(liveTimers()==0); combat=false; safety('ready'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); assert(BuffTap.action)")
test('Quick target uses its own threshold at click', "BuffTap.db.friendlyTarget=true; BuffTap.db.targetSeconds=300; aura('target',5232,'Mark of the Wild',200); refresh(); assert(BuffTap.action.quickTarget); BuffTap.button.scripts.PreClick(nil,'LeftButton',false); assert(BuffTap.action and BuffTap.button.attrs.spell==5232)")
test('Unrelated target changes are idle with target mode off', "BuffTap:ResetStats(); for i=1,100 do BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED') end; assert(BuffTap.stats.refreshes==0); assert(liveTimers()==0)")
test('Unwatched raid auras and unrelated item/spell loads are ignored', "BuffTap:ResetStats(); for i=1,100 do BuffTap.events.scripts.OnEvent(nil,'UNIT_AURA','raid1'); BuffTap.events.scripts.OnEvent(nil,'ITEM_DATA_LOAD_RESULT',777); BuffTap.events.scripts.OnEvent(nil,'SPELL_DATA_LOAD_RESULT',777) end; advance(1); assert(BuffTap.stats.refreshes==0)")
test('Repeated wake replacement leaves only one timer', "for i=1,100 do BuffTap:ScheduleWake(1000-i,'test') end; assert(liveTimers()==1); BuffTap:CancelWakeTimer(); assert(liveTimers()==0)")
test('Rapid target changes keep a bounded timer set', "BuffTap.db.friendlyTarget=true; for i=1,100 do BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED') end; assert(liveTimers()<=4)")
test('Threshold wake restores action at the configured time', "BuffTap.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild',100,1800); refresh(); assert(not BuffTap.action); advance(56); assert(BuffTap.action and BuffTap.action.needState=='expiring')")
test('Unknown external range is never a castable action', "BuffTap.db.group=true; BuffTap.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild'); C_Spell.IsSpellInRange=function() return nil end; refresh(); assert(not BuffTap.action); assert(BuffTap.rangeBlocked)")
test('Smart group does not count out of range members', "spell(21849,'Gift of the Wild',50); BuffTap.db.group=true; BuffTap.db.groupNeed=3; UnitLevel=function() return 60 end; C_Spell.IsSpellInRange=function(id,u) return u~='party2' end; refresh(); assert(not BuffTap.action.groupCast)")
test('Smart group chooses group spell for verified recipients', "spell(21849,'Gift of the Wild',50); BuffTap.db.group=true; UnitLevel=function() return 60 end; refresh(); assert(BuffTap.action.id==21849 and BuffTap.action.groupCount==3)")
test('Higher priority single stays ahead of lower group family', "spell(21849,'Gift of the Wild',50); BuffTap.db.group=true; UnitLevel=function() return 60 end; BuffTap.db.priorities.thorns=1; BuffTap.db.priorities.motw=2; refresh(); assert(BuffTap.action.id==467)")
test('Group downrank never exceeds recipient level', "spell(6756,'Mark of the Wild',20); BuffTap.db.group=true; BuffTap.db.buffs.thorns=false; aura('player',6756,'Mark of the Wild'); refresh(); assert(BuffTap.action.id==5232 and BuffTap.action.target=='party1')")
test('Malformed saved keys, priorities and group maps recover', "BuffTapDB.keys={true,{},'CTRL-B','CTRL-B'}; BuffTapDB.priorities={motw=0/0,thorns='bad'}; BuffTapDB.buffGroups={motw='bad',thorns={[2]=false}}; BuffTap:InitDB(); refresh(); assert(#BuffTap.db.keys==1 and BuffTap.db.keys[1]=='CTRL-B'); assert(BuffTap.db.priorities.motw==nil); assert(BuffTap.db.buffGroups.thorns[1]==true)")
test('Old overlay and threshold settings migrate', "BuffTapDB={seconds=8,showRemaining=true,showGroupIndicator=false}; BuffTap:InitDB(); assert(BuffTap.db.seconds==45 and BuffTap.db.showTimer and not BuffTap.db.showGroupBadge)")
test('All options pages build and move control opens', "BuffTap:Options(); assert(#BuffTap.options.pages==6); BuffTap:MoveAnchor(); assert(BuffTap.anchor.shown); BuffTap:CaptureBinding(); assert(BuffTap.capture.shown)")
test('Consumables default off and never query inventory at idle', "refresh(); assert(not BuffTap.db.consumablesEnabled and countCalls==0)")
test('Whitelist item creates exact secure item action', "stock(13510,17626); consumables('flask'); refresh(); assert(BuffTap.action.itemID==13510); assert(BuffTap.button.attrs.type1=='item' and BuffTap.button.attrs.item=='item:13510')")
test('Physical mouse down does not block mouse up item use', "stock(13510,17626); consumables('flask'); refresh(); BuffTap.button.scripts.PreClick(nil,'LeftButton',true); BuffTap.button.scripts.PostClick(nil,'LeftButton',true); BuffTap.button.scripts.PreClick(nil,'LeftButton',false); assert(BuffTap.action and BuffTap.button.attrs.item=='item:13510'); bags[13510]=4; BuffTap.button.scripts.PostClick(nil,'LeftButton',false); assert(BuffTap.consumablePending.flask>now)")
test('Right click never marks an item consumed', "stock(13510,17626); consumables('flask'); refresh(); BuffTap.button.scripts.PreClick(nil,'RightButton',false); BuffTap.button.scripts.PostClick(nil,'RightButton',false); assert(not BuffTap.itemAttempt and not BuffTap.consumablePending)")
test('Successful item spell confirms settling, failed clicks do not', "stock(13510,17626); consumables('flask'); refresh(); BuffTap.button.scripts.PreClick(nil,'LeftButton',true); BuffTap.events.scripts.OnEvent(nil,'UNIT_SPELLCAST_FAILED','player','cast',17626); assert(not BuffTap.consumablePending); BuffTap.events.scripts.OnEvent(nil,'UNIT_SPELLCAST_SUCCEEDED','player','cast',17626); assert(BuffTap.consumablePending.flask>now)")
test('Disappearing bag item rejected during prepare and click', "stock(13510,17626); consumables('flask'); refresh(); local action=BuffTap.action; bags[13510]=0; BuffTap:Commit(action,'test'); assert(not BuffTap.action); bags[13510]=1; BuffTap:InvalidateConsumables(); refresh(); bags[13510]=0; BuffTap.button.scripts.PreClick(nil,'LeftButton',false); assert(not BuffTap.action)")
test('Unloaded metadata cannot create an item action', "stock(13510,17626); items[13510].loaded=false; consumables('flask'); refresh(); assert(not BuffTap.action); items[13510].loaded=true; BuffTap.events.scripts.OnEvent(nil,'ITEM_DATA_LOAD_RESULT',13510,true); advance(.1); assert(BuffTap.action.itemID==13510)")
test('Questionmark icon cannot create an item action', "stock(13510,17626); items[13510].icon=134400; consumables('flask'); refresh(); assert(not BuffTap.action)")
test('Changed mapping is quarantined locally and Auto falls back', "stock(274273,99999); stock(13510,17626); consumables('flask'); refresh(); assert(BuffTap.itemQuarantine[274273]); assert(BuffTap.action.itemID==13510)")
test('A broken preferred item does not block another family', "stock(13510,99999); stock(250350,1250985); consumables('flask'); BuffTap.db.consumableFamilies.ferocity=true; refresh(); assert(BuffTap.action.itemID==250350)")
test('Food eating aura suppresses repeated use until Well Fed', "stock(250071,1248401); consumables('food'); aura('player',1248401,'Nutritious Food',20,30); refresh(); assert(not BuffTap.action); auras={}; aura('player',1248422,'Localized food buff',800,900); refresh(); assert(not BuffTap.action)")
test('Existing flask recognized by ID regardless of language', "stock(13510,17626); consumables('flask'); aura('player',17628,'Localized supreme power',3600,7200); refresh(); assert(not BuffTap.action)")
test('Inventory cache is not rescanned on ordinary aura refreshes', "stock(13510,17626); consumables('flask'); aura('player',17626,'Titans',3600,7200); refresh(); local before=countCalls; for i=1,100 do BuffTap:Refresh() end; assert(countCalls==before)")
test('Water Shield satisfies Lightning Shield without overwriting', "playerClass='SHAMAN'; spell(324,'Lightning Shield'); spell(408510,'Water Shield'); aura('player',408510,'Water Shield',500,600); refresh(); assert(not BuffTap.action); auras={}; BuffTap.db.buffs['water-shield']=true; refresh(); assert(BuffTap.action.id==408510)")
test('Missing rogue poison is a manual unbound alert', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); refresh(); assert(BuffTap.action and BuffTap.action.source=='weapon-reminder' and BuffTap.action.slot==16); assert(not BuffTap.button.attrs.type1 and not next(bindings))")
test('Weapon enchant event clears a satisfied manual alert', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); refresh(); weaponEnchants[16]={enchantID=323,remainingTimeMs=1800000,chargesRemaining=0,hasExpirationTime=true}; BuffTap.events.scripts.OnEvent(nil,'WEAPON_ENCHANT_CHANGED'); advance(.1); assert(not BuffTap.action and not next(bindings))")
test('Coated main hand advances reminder to off hand', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); equipWeapon(17,9002); weaponEnchants[16]={enchantID=323,remainingTimeMs=1800000,chargesRemaining=0,hasExpirationTime=true}; refresh(); assert(BuffTap.action and BuffTap.action.slot==17 and BuffTap.action.manual); assert(liveTimers()==0)")
test('Shield off hand does not request a poison', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); weaponEnchants[16]={enchantID=323,remainingTimeMs=1800000,chargesRemaining=0,hasExpirationTime=true}; equipShield(17,9002); refresh(); assert(not BuffTap.action)")
test('Unreadable weapon enchant state fails closed', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); C_PaperDollInfo=nil; refresh(); assert(not BuffTap.action and not next(bindings))")
test('Unreadable main hand does not hide missing off hand', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); equipWeapon(17,9002); weaponEnchants[16]='malformed'; refresh(); assert(BuffTap.action and BuffTap.action.slot==17 and BuffTap.action.manual)")
test('Zero item sentinel is treated as an empty hand', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipped[16]=0; equipWeapon(17,9002); refresh(); assert(BuffTap.action and BuffTap.action.slot==17)")
test('Unchanged manual reminder uses the safe fast path', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); refresh(); local before=clearBindingCalls; refresh(); assert(clearBindingCalls==before and BuffTap.action and BuffTap.action.manual and not BuffTap.button.attrs.type1)")
test('Castable class buff precedes manual weapon reminder', "playerClass='SHAMAN'; spells={}; book={}; spell(324,'Lightning Shield'); spell(8232,'Windfury Weapon'); equipWeapon(16,9001); refresh(); assert(BuffTap.action.id==324 and not BuffTap.action.manual); aura('player',324,'Lightning Shield'); refresh(); assert(BuffTap.action.source=='weapon-reminder')")
test('Castable consumable precedes manual weapon reminder', "playerClass='ROGUE'; spells={}; book={}; spell(8679,'Instant Poison'); equipWeapon(16,9001); stock(13510,17626); consumables('flask'); refresh(); assert(BuffTap.action.source=='consumable' and BuffTap.action.itemID==13510)")
test('Camp Benefits reports exact granted additions', "aura('player',1229741,'Camp Benefits',3000,3600); playerAuras[1230124]={spellId=1230124}; playerAuras[1229513]={spellId=1229513}; local camp=BuffTap:CampState(); assert(camp.active and #camp.benefits==2 and camp.benefits[1].name=='First Aid Kit' and camp.benefits[2].name=='Incense Candle')")
test('Catalog excludes known wrong spell IDs', "local function has(key,id) for _,v in ipairs(BuffTap:FindBuff(key).ranks) do if v==id then return true end end return false end; assert(has('natures-grasp',17329) and not has('natures-grasp',17354)); assert(not has('aspect-hawk',14323)); assert(has('lightning-shield',945) and not has('lightning-shield',10400))")
test('New Aspect and Seal IDs remain known-spell gated', "playerClass='PALADIN'; BuffTap.db.buffs['seal-fury']=true; refresh(); assert(not BuffTap.action); spell(1311649,'Seal of Fury'); refresh(); assert(BuffTap.action.id==1311649)")
test('No permanent OnUpdate on supported client', "assert(BuffTap.events.scripts.OnUpdate==nil)")

test('Group reagent missing falls back to single', "spell(21849,'Gift of the Wild',50); bags[17021]=0; BuffTap.db.group=true; UnitLevel=function() return 60 end; refresh(); assert(BuffTap.action.id==5232)")
test('Confirmed flask use without effect is quarantined after settling', "stock(13510,17626); consumables('flask'); refresh(); BuffTap.button.scripts.PreClick(nil,'LeftButton',false); bags[13510]=4; BuffTap.button.scripts.PostClick(nil,'LeftButton',false); advance(6); assert(BuffTap.itemQuarantine[13510]); assert(not BuffTap.action)")
test('Confirmed flask with effect does not quarantine', "stock(13510,17626); consumables('flask'); refresh(); BuffTap.button.scripts.PreClick(nil,'LeftButton',false); bags[13510]=4; BuffTap.button.scripts.PostClick(nil,'LeftButton',false); aura('player',17626,'Titans',3600,7200); advance(6); assert(not BuffTap.itemQuarantine[13510] and not BuffTap.action)")
test('Saved per-buff group overrides retain mixed state', "local b=BuffTap:FindBuff('motw'); local map=BuffTap:EnsureBuffGroups(b); map[2]=false; BuffTap:InitDB(); assert(BuffTap:GroupColumnState(2)=='mixed'); BuffTap:SetRaidGroupColumn(2,true); assert(BuffTap:GroupColumnState(2)=='on' and BuffTap.db.buffGroups.motw==nil)")
test('Greater blessing never replaces higher-priority owned family', "playerClass='PALADIN'; spells={}; book={}; spell(20217,'Blessing of Kings',20); spell(25898,'Greater Blessing of Kings',60); spell(19740,'Blessing of Might',4); spell(25782,'Greater Blessing of Might',52); UnitLevel=function() return 60 end; BuffTap.db.group=true; BuffTap.db.buffs.bom=true; for _,u in ipairs({'player','party1','party2'}) do aura(u,20217,'Blessing of Kings') end; refresh(); assert(not BuffTap.action)")
test('Raid subgroup assignments exclude unassigned recipients', "BuffTap.db.group=true; BuffTap.db.buffs.thorns=false; IsInRaid=function() return true end; GetNumGroupMembers=function() return 3 end; UnitExists=function(u) return u=='player' or u:match('^raid')~=nil end; UnitIsUnit=function(a,b) return a==b or a=='raid1' and b=='player' end; GetRaidRosterInfo=function(i) return 'Member',0,i==3 and 2 or 1 end; BuffTap.db.raidGroups[2]=false; aura('player',5232,'Mark of the Wild'); aura('raid2',5232,'Mark of the Wild'); BuffTap:InvalidateRoster(); refresh(); assert(not BuffTap.action)")
test('Dead and offline targets skipped without blocking other members', "BuffTap.db.group=true; BuffTap.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild'); UnitIsConnected=function(u) return u~='party1' end; refresh(); assert(BuffTap.action.target=='party2'); UnitIsDeadOrGhost=function(u) return u=='party2' end; refresh(); assert(not BuffTap.action)")
test('Empty spellbook retry stops and book event recovers', "spells={}; book={}; C_SpellBook.GetNumSpellBookSkillLines=function() return 0 end; BuffTap.bookDirty=true; refresh(); advance(100); assert(liveTimers()==0); seed(); C_SpellBook.GetNumSpellBookSkillLines=function() return 1 end; BuffTap.events.scripts.OnEvent(nil,'SPELLS_CHANGED'); advance(.1); assert(BuffTap.action)")
test('Metadata changes in combat applied safely on exit', "combat=true; safety('blocked'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_DISABLED'); spells[5232].known=false; BuffTap.events.scripts.OnEvent(nil,'SPELLS_CHANGED'); BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(not BuffTap.action); combat=false; safety('ready'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); assert(BuffTap.action.id==1126)")
test('Missing optional item APIs do not break class spell selection', "C_Item=nil; BuffTap.db.consumablesEnabled=true; BuffTap.db.consumableFamilies.flask=true; refresh(); assert(BuffTap.action.id==5232)")
test('Appearance changes preserve selected secure action', "BuffTap.db.size=24; BuffTap.db.showTimer=true; BuffTap.db.showGroupBadge=true; BuffTap.db.x=30; BuffTap.appearance=nil; refresh(); assert(BuffTap.action.id==5232 and BuffTap.button.attrs.spell==5232)")
test('Hundreds of idle aura refreshes reuse rank and roster caches', "BuffTap:ResetStats(); for i=1,100 do BuffTap:Refresh() end; assert(BuffTap.stats.auraScans==0); assert(BuffTap.stats.resolveBuilds==0); assert(BuffTap.stats.resolveHits>0); assert(liveTimers()==0)")
test('Every target class advances Mark to Thorns', "for _,class in ipairs(BuffTap.RecipientClasses) do auras={}; UnitClass=function(u) return 'Class',u=='player' and 'DRUID' or class end; BuffTap.db.friendlyTarget=true; refresh(); assert(BuffTap.action.key=='motw' and BuffTap.action.quickTarget); aura('target',5232,'Mark of the Wild'); refresh(); assert(BuffTap.action.key=='thorns' and BuffTap.action.quickTarget,class); aura('target',467,'Thorns'); refresh(); assert(not BuffTap.action.quickTarget) end")
test('Group class defaults and overrides share single and group families', "local b=BuffTap:FindBuff('bom'); assert(not BuffTap:GroupClassAllowed(b,'WARLOCK')); BuffTap.db.buffClasses.bom={WARLOCK=true,WARRIOR=false}; assert(BuffTap:GroupClassAllowed(BuffTap:FindBuff('gbom'),'WARLOCK')); assert(not BuffTap:GroupClassAllowed(b,'WARRIOR')); BuffTap:InitDB(); assert(BuffTap.db.buffClasses.bom.WARRIOR==false)")
test('Party class and group filters intersect', "BuffTap.db.group=true; BuffTap.db.buffs.motw=false; aura('player',467,'Thorns'); UnitClass=function(u) return 'Class',u=='player' and 'DRUID' or 'WARLOCK' end; refresh(); assert(not BuffTap.action); BuffTap.db.buffClasses.thorns={WARLOCK=true}; refresh(); assert(BuffTap.action.target=='party1'); BuffTap.db.buffGroups.thorns={[1]=false}; refresh(); assert(not BuffTap.action); BuffTap.db.friendlyTarget=true; refresh(); assert(BuffTap.action.quickTarget and BuffTap.action.key=='thorns')")
test('Class filters leave personal buffs independent', "BuffTap.db.buffClasses.motw={DRUID=false}; refresh(); assert(BuffTap.action.target=='player' and BuffTap.action.key=='motw')")
test('Group cast falls back when subgroup contains excluded class', "spell(21849,'Gift of the Wild',50); UnitLevel=function() return 60 end; UnitClass=function(u) return 'Class',u=='party2' and 'WARLOCK' or 'DRUID' end; BuffTap.db.group=true; BuffTap.db.groupNeed=2; BuffTap.db.buffClasses.motw={WARLOCK=false}; refresh(); assert(BuffTap.action.key=='motw' and not BuffTap.action.groupCast)")
test('Paladin explicit target follows priority without class filters', "playerClass='PALADIN'; spells={}; book={}; spell(19740,'Blessing of Might',4); spell(19742,'Blessing of Wisdom',4); BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bom=true; BuffTap.db.buffs.bow=true; BuffTap.db.priorities.bom=1; BuffTap.db.priorities.bow=2; BuffTap.db.friendlyTarget=true; UnitClass=function(u) return 'Class',u=='player' and 'PALADIN' or 'WARLOCK' end; refresh(); assert(BuffTap.action.key=='bom' and BuffTap.action.quickTarget); aura('target',19740,'Blessing of Might'); refresh(); assert(not BuffTap.action.quickTarget); BuffTap.db.priorities.bow=1; BuffTap.db.priorities.bom=2; refresh(); assert(BuffTap.action.key=='bow' and BuffTap.action.quickTarget)")
test('Paladin group sorting skips filtered higher priority family', "playerClass='PALADIN'; spells={}; book={}; spell(19740,'Blessing of Might',4); spell(19742,'Blessing of Wisdom',4); BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bom=true; BuffTap.db.buffs.bow=true; BuffTap.db.priorities.bom=1; BuffTap.db.priorities.bow=2; BuffTap.db.group=true; UnitClass=function(u) return 'Class',u=='player' and 'PALADIN' or 'WARLOCK' end; aura('player',19740,'Blessing of Might'); refresh(); assert(BuffTap.action.key=='bow' and BuffTap.action.target=='party1'); BuffTap.db.buffClasses.bom={WARLOCK=true}; refresh(); assert(BuffTap.action.key=='bom' and BuffTap.action.target=='party1')")
