test('Class option toggles and reset persist correctly', "BuffTap:Options(); local row; for _,r in ipairs(BuffTap.options.assignRows) do if r.def.key=='thorns' then row=r end end; assert(row and not row.classes.WARLOCK:GetChecked()); local c=row.classes.WARLOCK; c:SetChecked(true); c.scripts.OnClick(c); assert(BuffTap.db.buffClasses.thorns.WARLOCK); row.resetClasses.scripts.OnClick(row.resetClasses); assert(BuffTap.db.buffClasses.thorns==nil)")
