test('Different Well Fed effect preserves the existing meal',"stock(6888,1248377); consumables('food'); aura('player',1249520,'Localized regeneration meal',800,900); refresh(); assert(not BuffTap.action)")
test('XP bonus alone does not substitute for a food buff',"stock(6888,1248377); consumables('food'); aura('player',1243969,'Food XP',800,900); refresh(); assert(BuffTap.action.itemID==6888)")
test('Explicit missing food never substitutes another item',"stock(250071,1248401); consumables('food'); local f=BuffTap:ConsumableFamily('food'); BuffTap:SetConsumableChoice(f,6888); refresh(); assert(not BuffTap.action and BuffTap:ConsumableChoiceID(f)==6888); stock(6888,1248377); BuffTap.events.scripts.OnEvent(nil,'BAG_UPDATE_DELAYED'); advance(.2); assert(BuffTap.action.itemID==6888)")
test('Selected elixir uses exact spell mapping',"stock(2457,2374); consumables('ferocity'); BuffTap:SetConsumableChoice(BuffTap:ConsumableFamily('ferocity'),2457); refresh(); assert(BuffTap.action.itemID==2457 and BuffTap.button.attrs.item=='item:2457')")
test('Existing different elixir is preserved even near expiration',"stock(2457,2374); consumables('ferocity'); BuffTap:SetConsumableChoice(BuffTap:ConsumableFamily('ferocity'),2457); aura('player',1250985,'Ferocity',1,1800); refresh(); assert(not BuffTap.action)")
test('Elixir default preserves legacy Ferocity preference',"stock(2457,2374); consumables('ferocity'); refresh(); assert(not BuffTap.action); stock(250350,1250985); BuffTap:InvalidateConsumables(); refresh(); assert(BuffTap.action.itemID==250350)")
test('Potion stock selection never becomes a secure use action',"stock(118,439); consumables('potion-stock'); local f=BuffTap:ConsumableFamily('potion-stock'); BuffTap:SetConsumableChoice(f,118); refresh(); assert(not BuffTap.action); local ok=BuffTap:ValidateConsumable({source='consumable',familyKey='potion-stock',itemID=118}); assert(not ok)")
test('Picker keeps absent choices and filters inventory',"stock(6888,1248377); BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); local f=BuffTap.itemPicker; f.search:SetText('Herb Baked'); BuffTap:UpdateConsumablePicker(); assert(f.rows[1].itemID==6888); bags[6888]=0; f.bags:SetChecked(false); BuffTap:InvalidateConsumables(); BuffTap:UpdateConsumablePicker(); assert(f.rows[1].stock.text:find('Out of stock')); f.rows[1].scripts.OnClick(f.rows[1]); assert(BuffTap.db.consumableChoices.food==6888); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); f.bags:SetChecked(true); f.search:SetText('Herb Baked'); BuffTap:UpdateConsumablePicker(); assert(f.rows[1].itemID==nil or not f.rows[1].shown)")
test('Expanded inventory uses cache on ordinary aura refresh',"stock(6888,1248377); consumables('food'); aura('player',1248406,'Well Fed',900,900); refresh(); local before=countCalls; for i=1,50 do BuffTap:Refresh() end; assert(countCalls==before)")
test('Picker scrolling clamps and search resets the visible range', "BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); local f=BuffTap.itemPicker; f.bags:SetChecked(false); BuffTap:UpdateConsumablePicker(); assert(f.maxOffset>8); f.scripts.OnMouseWheel(f,-1000); assert(f.offset==f.maxOffset and f.rows[8].shown); f.search:SetText('Herb Baked'); f.search.scripts.OnTextChanged(f.search); assert(f.offset==0 and f.rows[1].itemID==6888 and not f.rows[2].shown)")
test('Auto and explicit selection remain mutually exclusive', "stock(6888,1248377); BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); local f=BuffTap.itemPicker; assert(f.auto.text:find('(o)',1,true)); assert(f.rows[1].mark.text=='( )'); f.rows[1].scripts.OnClick(f.rows[1]); assert(BuffTap:ConsumableChoiceID(f.family)==6888 and f.rows[1].mark.text=='(o)' and f.auto.text:find('( )',1,true)); f.auto.scripts.OnClick(f.auto); assert(not BuffTap:ConsumableChoiceID(f.family) and f.rows[1].mark.text=='( )')")
test('Missing selected food remains visible in selection summary', "BuffTap:Options(); local family=BuffTap:ConsumableFamily('food'); BuffTap:SetConsumableChoice(family,6888); BuffTap:ChooseConsumable(family); local f=BuffTap.itemPicker; assert(f.bags:GetChecked() and f.summary.text:find('Herb Baked Egg') and f.summary.text:find('0 in bags')); assert(not f.rows[1].shown); assert(BuffTap:ConsumableChoiceID(family)==6888)")
test('Group buff selection and all-classes controls keep other assignments', "BuffTap:Options(); local f=BuffTap.options; assert(f.assignRows[1].shown and not f.assignRows[2].shown); f.assignButtons[2].scripts.OnClick(f.assignButtons[2]); assert(not f.assignRows[1].shown and f.assignRows[2].shown); local r=f.assignRows[2]; r.allClasses.scripts.OnClick(r.allClasses); for _,class in ipairs(BuffTap.RecipientClasses) do assert(BuffTap:GroupClassAllowed(r.def,class)) end; assert(not BuffTap.db.buffClasses.motw); r.resetClasses.scripts.OnClick(r.resetClasses); assert(not BuffTap.db.buffClasses.thorns)")
test('Picker closes with options and combat prevents changes', "stock(6888,1248377); BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); local f=BuffTap.itemPicker; BuffTap.options:Hide(); assert(not f.shown); BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); combat=true; f.rows[1].scripts.OnClick(f.rows[1]); assert(not BuffTap:ConsumableChoiceID(f.family)); f.scripts.OnEvent(f,'PLAYER_REGEN_DISABLED'); assert(not f.shown)")
test('Item data event replaces placeholder with the native item icon', "stock(6888,1248377); items[6888].loaded=false; items[6888].icon=134400; BuffTap:Options(); BuffTap:ChooseConsumable(BuffTap:ConsumableFamily('food')); local f=BuffTap.itemPicker; assert(f.rows[1].icon.texture==134400); items[6888].loaded=true; items[6888].icon=133902; f.scripts.OnEvent(f,'ITEM_DATA_LOAD_RESULT',6888); assert(f.rows[1].icon.texture==133902)")
Path(__file__).with_name('last-run.txt').write_text('\n'.join('PASS '+x for x in tests)+'\n\n'+str(len(tests))+' scenarios passed under Lua 5.1. Mocked APIs; no in-client cast or visual verification.\n')
